package com.agacostays.payroll.controller; import com.agacostays.payroll.dto.request.CreditSalaryRequest;import com.agacostays.payroll.dto.response.*;import com.agacostays.payroll.security.CurrentUserProvider;import com.agacostays.payroll.service.PayrollService;import jakarta.validation.Valid;import org.springframework.http.ResponseEntity;import org.springframework.web.bind.annotation.*;@RestController @RequestMapping("/api/manager/payroll") public class SalaryCreditController{final PayrollService s;final CurrentUserProvider c;public SalaryCreditController(PayrollService s,CurrentUserProvider c){this.s=s;this.c=c;}@PostMapping("/credit-salaries") public ResponseEntity<ApiResponse<java.util.List<SalaryCreditResponse>>> all(@RequestParam int month,@RequestParam int year,@Valid @RequestBody CreditSalaryRequest r){return ResponseEntity.ok(ApiResponse.ok("Salaries credited",s.creditAll(month,year,r.paymentMode(),c.userId())));}@PostMapping("/staff/{staffId}/credit-salary") public ResponseEntity<ApiResponse<SalaryCreditResponse>> one(@PathVariable Long staffId,@RequestParam Long payrollId,@Valid @RequestBody CreditSalaryRequest r){return ResponseEntity.ok(ApiResponse.ok("Salary credited",s.credit(payrollId,r.paymentMode(),c.userId())));}@PostMapping("/{payrollId}/credit") public ResponseEntity<ApiResponse<SalaryCreditResponse>> creditAlias(@PathVariable Long payrollId,@Valid @RequestBody CreditSalaryRequest r){return ResponseEntity.ok(ApiResponse.ok("Salary credited",s.credit(payrollId,r.paymentMode(),c.userId())));}}
